insert into public.questions (id, prompt, question_type, options, position, tier_primary, tier_secondary) values
  ('2ed6bd1d-14a9-5ebb-b892-bf8e150bd4fd', 'Was ist der Unterschied zwischen generativer KI (generative AI) und diskriminativer KI (discriminative AI)?', 'multiple_choice', '["Generative AI ist immer kostenlos, discriminative AI ist immer kostenpflichtig", "Generative AI kann neue Inhalte erzeugen (z. B. Text oder Bild), discriminative AI klassifiziert bzw. unterscheidet vorgegebene Inputs (z. B. Hund oder Katze auf einem Bild)", "Beide Begriffe bedeuten dasselbe, es sind nur unterschiedliche Marketing-Namen", "Generative AI läuft nur lokal, discriminative AI nur in der Cloud"]'::jsonb, 1, 'T4', null),
  ('73193755-3ef4-5436-9ca7-6e2d6ae2e4c1', 'Warum tun sich Sprachmodelle schwer damit, Buchstaben in einem Wort korrekt zu zählen?', 'multiple_choice', '["Weil dafür immer ein externer Taschenrechner gebraucht wird, der oft ausfällt", "Weil deutsche Wörter grundsätzlich nicht analysiert werden können", "Weil das Wort zu kurz für eine statistische Auswertung ist", "Weil das Modell Text nicht in einzelnen Buchstaben, sondern in Tokens verarbeitet"]'::jsonb, 3, 'T4', null),
  ('c37b8440-7d92-5ed8-a71f-d136aad451ea', 'Wofür steht die Abkürzung "API"?', 'multiple_choice', '["Automated Program Integration", "Application Process Identifier", "Application Programming Interface", "Artificial Programming Index"]'::jsonb, 7, 'T3', null),
  ('183b1940-020d-5c4c-998a-23d231898f71', 'Der erste Harry-Potter-Band ("Der Stein der Weisen") hat ca. 77.000 Wörter. Wie oft passt er ungefähr in eine Textmenge von 1 Million Tokens?', 'estimation', null, 8, 'T4', null),
  ('2da85511-9364-54e2-a93b-268fc13ce66f', 'Was bezeichnet man im Webhook-Kontext als "Payload"?', 'multiple_choice', '["Die Daten (meist als JSON), die beim Aufruf an den Webhook übergeben werden", "Die Anzahl der Knoten in einem Workflow", "Die maximale Antwortzeit eines Servers", "Den Namen des Entwicklers, der die Webhook gebaut hat"]'::jsonb, 9, 'T3', null),
  ('2c95cd4c-86a3-57ce-9328-7a60e6756044', 'Wie heißt das agentische Design-Pattern, bei dem ein LLM entscheidet, in welchen von mehreren Lösungspfaden eine Anfrage weitergeleitet wird?', 'multiple_choice', '["Evaluator-Optimizer", "Routing", "Parallelization", "Prompt Chaining"]'::jsonb, 10, 'T2', null),
  ('6f0a8b60-cece-56da-9da5-8c9a167d5c72', 'Was ist der entscheidende technische Unterschied zwischen der Nutzung eines LLM über Chat-Interface (z. B. ChatGPT) und über die reine API?', 'multiple_choice', '["Nur die API kann strukturierten Output liefern", "Die API erhält bei jedem Aufruf nur den aktuellen Input; das Chat-Interface hängt im Hintergrund den bisherigen Gesprächsverlauf an", "Das Chat-Interface nutzt ein anderes Sprachmodell als die API", "Die API kann keine langen Texte verarbeiten"]'::jsonb, 11, 'T2', 'T4'),
  ('dc18b86b-5d34-5c1d-8b55-5b5535598896', 'Warum ist eine E-Mail-Adresse als alleiniger, dauerhafter Primärschlüssel für einen Nutzer-Datensatz riskant?', 'multiple_choice', '["E-Mail-Adressen ändern sich automatisch alle 30 Tage", "Nutzer können ihre E-Mail-Adresse ändern — ein vermeintlich stabiler Schlüssel ist es damit nicht wirklich", "E-Mail-Adressen enthalten niemals Zahlen", "E-Mail-Adressen sind immer maximal 10 Zeichen lang"]'::jsonb, 13, 'T3', null),
  ('1a7ffa2f-8186-5f04-a357-d8194c8e6539', 'Welches Land steht hinter dem Sprachmodell "Mistral", als europäische Alternative zu US-Anbietern?', 'multiple_choice', '["Niederlande", "Deutschland", "Frankreich", "Schweden"]'::jsonb, 14, 'T4', null),
  ('092e8038-78ab-58b1-a478-be12c0de20ac', 'Im Kurs wurde unter Berufung auf eine McKinsey-Analyse ein hoher Anteil an KI-Transformationsprojekten genannt, die in der Pilotphase steckenbleiben bzw. ihre ROI-Ziele verfehlen ("Pilot Purgatory"). Wie hoch war die im Kurs genannte Schätzung ungefähr?', 'estimation', null, 15, 'T5', null),
  ('cdfd07e7-e372-597f-b0b9-e285299a58fe', 'Was bedeutet eine niedrige "Perplexity" bei einem Sprachmodell?', 'multiple_choice', '["Das Modell kann keine Internetquellen finden", "Das Modell arbeitet besonders langsam", "Das Modell sagt die tatsächlich beobachtete Tokenfolge im Mittel gut vorher (ein Maß für Vorhersagbarkeit, nicht direkt für Textqualität)", "Das Modell kostet besonders viel pro Token"]'::jsonb, 16, 'T4', null),
  ('f1a7893d-1c7b-5eae-8f38-8667c9e4da86', 'Welches ist KEIN vorgestelltes n8n-"Design Pattern" für Automatisierungs-Workflows?', 'multiple_choice', '["Notify Pattern", "Classification Pattern", "Encryption Pattern", "Extraction Pattern"]'::jsonb, 17, 'T3', null),
  ('aceb6773-50f3-5c5e-929d-c6a0136adde2', 'Wann benutzt man in n8n einen **If**-Knoten statt eines **Switch**-Knotens?', 'multiple_choice', '["Wenn es genau 2 mögliche Pfade gibt", "Wenn Daten aus einer Datenbank kommen", "Wenn es mehr als 2 mögliche Pfade gibt", "Wenn ein Sub-Workflow aufgerufen wird"]'::jsonb, 18, 'T3', null),
  ('f7d32bc0-10e1-5dd3-b046-ec21b7ae4d12', 'Wer hat das Model Context Protocol (MCP) entwickelt, mit dem KI-Modelle standardisiert auf externe Tools/APIs zugreifen können?', 'multiple_choice', '["Anthropic", "das n8n-Team", "Google DeepMind", "OpenAI"]'::jsonb, 19, 'T2', null),
  ('a9dacabc-58cb-5785-8033-04834e7fb362', 'Was verbietet die n8n-Lizenz (Sustainable Use License) ohne kommerzielle Sonderregelung?', 'multiple_choice', '["n8n lokal auf dem eigenen Rechner zu installieren", "n8n selbst als gehosteten Dienst weiterzuverkaufen bzw. Kunden Zugang zu einer eigenen n8n-Instanz als Produkt anzubieten", "n8n privat kostenlos zu nutzen", "Den Quellcode von n8n auf GitHub einzusehen"]'::jsonb, 21, 'T3', 'T5'),
  ('f1a022a6-93a8-574b-8575-90c433a306be', 'Im Kurs wurde unter Berufung auf McKinsey genannt, dass einzelne KI-Use-Cases deutlich häufiger scheitern als klassische IT-Projekte (dort ca. 30 %). Welcher Anteil wurde im Kurs für gescheiterte KI-Use-Cases genannt?', 'estimation', null, 22, 'T5', null),
  ('3963b90b-784a-599f-aae8-a8515ad0f8c5', 'Welches Kriterium ist ein Hauptgrund, warum bei einer Aktion ein Mensch (Human in the Loop) eingebunden werden sollte?', 'multiple_choice', '["Die Aktion ist schwer oder gar nicht umkehrbar (z. B. eine bereits versendete E-Mail)", "Die Aktion verwendet zwingend ein Sprachmodell", "Die Aktion dauert länger als 5 Sekunden", "Die Aktion betrifft eine Bestellung unter 10 Euro"]'::jsonb, 23, 'T5', 'T2'),
  ('68e7529b-3db2-555e-a427-a8d81a0da8b7', 'Wie hoch ist laut EU AI Act die höchstmögliche Strafe für die schwerwiegendste Kategorie von Verstößen (z. B. verbotene KI-Praktiken)?', 'multiple_choice', '["20 Mio. € oder 4 % des weltweiten Jahresumsatzes", "35 Mio. € oder 7 % des weltweiten Jahresumsatzes (jeweils der höhere Betrag)", "1 % des EU-Umsatzes", "pauschal 10 Mio. €"]'::jsonb, 26, 'T5', null),
  ('79eb7557-3341-5dd6-8198-b9fa9ad361c2', 'Wie erklärt sich der zentrale Unterschied zwischen einem **Workflow** und einem **Agenten**?', 'multiple_choice', '["Ein Agent baut sich seinen Pfad vom Trigger zum Ziel selbst; beim Workflow legt der Mensch die Struktur vorher fest", "Ein Workflow läuft nur einmal, ein Agent läuft dauerhaft im Hintergrund", "Ein Workflow kann keine KI-Knoten enthalten, ein Agent nur KI-Knoten", "Ein Agent ist immer teurer, aber niemals fehleranfällig"]'::jsonb, 27, 'T2', null),
  ('ff9b4d61-b605-50f6-9785-c70e7f490a91', 'Welche drei Merkmale wurden im Kurs als Definition eines "Agenten" genannt (neben "Augmented LLM")?', 'multiple_choice', '["Trigger, Node, Output", "Zielorientierung (Goal), Aktion (Action), Werkzeuggebrauch/Reasoning (ReAct-Pattern)", "Login, Datenbank, API-Key", "Geschwindigkeit, Kosten, Skalierbarkeit"]'::jsonb, 28, 'T2', null),
  ('2913cc32-31da-56ef-8dee-d384a90bd82c', 'Was ist der zentrale Unterschied zwischen Pseudonymisierung und Anonymisierung personenbezogener Daten?', 'multiple_choice', '["Pseudonymisierung betrifft nur Bilddaten, Anonymisierung nur Textdaten", "Es handelt sich um zwei Begriffe für denselben Vorgang", "Anonymisierung ist DSGVO-rechtlich nicht anerkannt", "Bei Pseudonymisierung ist ein Rückschluss auf die Person über Zusatzwissen theoretisch noch möglich, bei Anonymisierung nicht mehr"]'::jsonb, 29, 'T5', null),
  ('0a04aaf7-b32b-54c7-9d2f-4b7d0b4d3803', 'Wofür steht die Abkürzung **RAG**, als "wahrscheinlich wichtigstes ML-Konzept der letzten Jahre" bezeichnet?', 'multiple_choice', '["Reasoning And Grounding", "Rule-based Agent Gateway", "Random Access Generator", "Retrieval Augmented Generation"]'::jsonb, 30, 'T1', null),
  ('e9647e7e-d76e-5b21-9186-f34786891b1c', 'Was bedeutet ein **kleiner Winkel** zwischen zwei Text-Embedding-Vektoren?', 'multiple_choice', '["Die beiden Texte stammen vom selben Autor", "Die beiden Texte sind exakt gleich lang", "Die beiden Texte enthalten widersprüchliche Aussagen", "Die beiden Texte behandeln ähnliche/verwandte Themen"]'::jsonb, 31, 'T1', 'T4'),
  ('2ce0ac2a-c7f1-537f-ac64-087b5a2f8d14', 'Welches 2017 veröffentlichte Paper wird als eigentlicher wissenschaftlicher Durchbruch hinter modernen Sprachmodellen genannt?', 'multiple_choice', '["\"BERT: Pre-training of Deep Bidirectional Transformers\"", "\"Playing Atari with Deep Reinforcement Learning\"", "\"Language Models are Few-Shot Learners\"", "\"Attention Is All You Need\""]'::jsonb, 32, 'T4', null),
  ('27c91b99-908a-5901-8914-497573e061cf', 'Warum kritisiert der Dozent, dass in einem Data Table **NULL** statt **0** für "nichts bestellt" gespeichert wird?', 'multiple_choice', '["NULL kann von n8n technisch gar nicht gespeichert werden", "NULL kostet mehr Speicherplatz als eine 0", "NULL \"vergiftet\" nachfolgende Berechnungen — Zahl + NULL ergibt wieder NULL", "NULL wird von Data Tables automatisch in Text umgewandelt"]'::jsonb, 33, 'T3', null),
  ('a046262a-3754-5875-a33e-f3aa538454dc', 'Was beschreibt der Begriff "Differential Privacy" (differenzielle Privatsphäre) im Kern?', 'multiple_choice', '["Ein mathematisches Rahmenwerk, das über gezielt eingefügtes Rauschen begrenzt, wie stark sich ein Ergebnis durch das Hinzufügen oder Entfernen einer einzelnen Person im Datensatz verändern darf", "Eine Verschlüsselung, die nur für Gesundheitsdaten gilt", "Ein Algorithmus, der zufällig 50 % aller Datensätze löscht", "Ein Tool, das automatisch Namen aus PDFs entfernt"]'::jsonb, 34, 'T5', 'T4'),
  ('0d5b8ff7-fdc0-5cf9-b272-b2b768919ed6', 'Wofür steht die Abkürzung **GPT**?', 'multiple_choice', '["Generative Pretrained Transformer", "Guided Prompt Technology", "General Purpose Tool", "Global Processing Terminal"]'::jsonb, 35, 'T4', null),
  ('f4a265d0-0d6b-5a3f-9691-07bb1615e661', 'Mit welchem Gedankenexperiment wird erklärt, dass ein LLM Symbole verarbeitet, ohne sie im menschlichen Sinne zu "verstehen"?', 'multiple_choice', '["Chinesischer Raum", "Schiff des Theseus", "Trolley-Problem", "Turing-Test"]'::jsonb, 36, 'T4', null),
  ('f88e4be3-079c-5737-a607-9224f40668cc', 'Welche drei grundlegenden Datenquellen-Typen für RAG-Systeme wurden im Kurs vorgestellt — und welche gehört NICHT dazu?', 'multiple_choice', '["Vektor-Datenbank (Vector Store)", "Key-Value-Store", "Relationale Datenbank", "Graphdatenbank"]'::jsonb, 37, 'T1', null),
  ('9216a580-e875-57a2-b55a-2169263382d2', 'Wie lautet die englische Abkürzung für die deutsche "Datenschutzgrundverordnung (DSGVO)"?', 'multiple_choice', '["CCPA", "GDPR", "HIPAA", "FISA"]'::jsonb, 38, 'T5', null),
  ('ccc18de0-c37e-51df-a0f5-4b52721fbad3', 'In welche drei Kategorien wurden im Kurs Kontext-Informationen für ein RAG-System bezüglich ihrer Nutzbarkeit eingeteilt?', 'multiple_choice', '["Wichtig, Unwichtig, Fraglich", "Public, Private, Confidential", "Merken, Verwerfen, Zustimmung einholen", "Speichern, Löschen, Anonymisieren"]'::jsonb, 39, 'T1', 'T5'),
  ('c1cb9958-d96d-5fc5-9587-d1cafdb2d4d5', 'Wie wird im Kurs der zentrale Unterschied zwischen einem "Workflow" und einem autonomen "Agenten" (z. B. Openclaw) erklärt?', 'multiple_choice', '["Workflows benötigen zwingend ein Sprachmodell, Agenten nicht", "Ein Workflow ist vorhersehbar/deterministisch, ein Agent handelt autonom und kann unvorhergesehene Dinge tun", "Agenten sind grundsätzlich günstiger im Betrieb", "Workflows können keine APIs ansprechen"]'::jsonb, 41, 'T2', null),
  ('e01b342d-cfe5-545c-a21b-7fd8bb3c6772', 'Wie nennt man den Versuch, ein LLM durch eine geschickte Rahmengeschichte dazu zu bringen, eigentlich blockierte Informationen preiszugeben?', 'multiple_choice', '["Fine-Tuning", "Hallucination", "Jailbreak", "Prompt Injection"]'::jsonb, 42, 'T5', null),
  ('55a8f9b5-1764-5e2c-af6a-e15cfb1d4706', 'Wie heißt die RAG-Technik, bei der das LLM zunächst eine hypothetische Antwort generiert und diese (statt der ursprünglichen Frage) für die Vektorsuche nutzt?', 'multiple_choice', '["Query Decomposition", "Chain-of-Thought", "Re-Ranking", "HyDE (Hypothetical Document Embeddings)"]'::jsonb, 43, 'T1', null),
  ('a4e01dac-e813-54b0-a6c6-ec50b33a9adf', 'Im Kurs wurde live getestet: "Describe apple" (klein) lieferte keine Firmeninformation, "Describe Apple" (groß) dagegen schon. Was demonstriert das?', 'multiple_choice', '["Sprachmodelle verarbeiten Text tokenbasiert, wodurch Groß-/Kleinschreibung das Ergebnis beeinflussen kann", "Claude hat einen speziellen Rechtschreibfilter", "Ein einmaliger Bug", "Browser-Cache-Effekt"]'::jsonb, 44, 'T4', 'T1'),
  ('8d7bb551-7024-5325-8220-0999960bc858', 'Warum kann eine übermäßig große, unkuratierte Wissensdatenbank ein RAG-System eher verschlechtern statt verbessern?', 'multiple_choice', '["Ältere Embedding-Modelle können keine großen Datenmengen verarbeiten", "Vektordatenbanken haben eine harte Obergrenze von 100 Dokumenten", "Es macht die relevante Information (\"die Nadel\") in der wachsenden Datenmenge (\"Heuhaufen\") schwerer auffindbar", "Größere Datenbanken benötigen mehr Rechenleistung fürs Chunking"]'::jsonb, 45, 'T1', null),
  ('5aea946e-0219-525c-9a6d-508a578fdd26', 'Was ist ein "Chunk" im Kontext von RAG-Systemen?', 'multiple_choice', '["Ein einzelnes, kleineres Text-Segment eines Dokuments, das separat vektorisiert und durchsucht wird", "Ein komplettes Dokument, unverändert in die Vektordatenbank geladen", "Der System-Prompt, der dem LLM vor jeder Anfrage übergeben wird", "Ein Cache für häufig gestellte Fragen"]'::jsonb, 46, 'T1', null),
  ('4ea531ea-2312-5098-9390-1a22727a1321', 'Eine Kette aus 4 hintereinandergeschalteten LLM-Knoten hat pro Knoten eine Erfolgswahrscheinlichkeit von 90 %. Wie hoch ist (gerundet) die Gesamt-Erfolgswahrscheinlichkeit der ganzen Kette?', 'estimation', null, 47, 'T2', 'T5'),
  ('96421b94-ad97-54a5-90b5-7ef5a09d92b2', 'Wie nennt man die Metrik, die misst, wie zuverlässig ein RAG-System bei einer Testfrage die tatsächlich richtige Quelle wiederfindet?', 'multiple_choice', '["Latency", "Precision", "F1-Score", "Recall"]'::jsonb, 48, 'T1', 'T5'),
  ('b31eb216-88a2-52b4-ae5d-006c1062aeec', 'Warum kann ein RAG-System mit sehr vielen abgelegten Vektoren (z. B. 1 Million) schlechter funktionieren als eines mit wenigen, gezielt relevanten Vektoren?', 'multiple_choice', '["Es entstehen automatisch doppelte Chunks", "Mehr irrelevanter Kontext verschlechtert das Signal-Rausch-Verhältnis (Nadel-im-Heuhaufen-Problem)", "Ältere Embedding-Modelle unterstützen keine großen Datenmengen", "Vektordatenbanken haben eine technische Obergrenze von 1.000 Einträgen"]'::jsonb, 49, 'T1', null),
  ('60bad66b-1c68-593e-8036-ebc1ab4d34c6', 'Wie heißt die Technik, bei der ein Dokumenten-Korpus zunächst in Cluster geteilt, zusammengefasst und diese Zusammenfassungen wieder eingebettet werden, um mehrere Abstraktionsebenen durchsuchbar zu machen?', 'multiple_choice', '["Semantic Chunking", "RAPTOR", "LangGraph", "Fine-Tuning"]'::jsonb, 50, 'T1', null),
  ('9ed12893-3e73-54bb-ba79-fc6b51977645', 'Wie nennt man das Verfahren, bei dem ein kleines Sprachmodell ("Student") darauf trainiert wird, die Ausgaben eines großen Sprachmodells ("Teacher") zu imitieren?', 'multiple_choice', '["Teacher-Student-Setup (Knowledge Distillation)", "Reinforcement Learning", "Prompt Engineering", "Fine-Tuning"]'::jsonb, 53, 'T4', null),
  ('6fa9952c-fc71-5423-a38f-8fb06071d569', 'Wie stuft der EU AI Act typische Recruiting-/Personalauswahl-Systeme grundsätzlich ein (Anhang III)?', 'multiple_choice', '["Minimal Risk", "High Risk", "Limited Risk", "Prohibited Use Case"]'::jsonb, 55, 'T5', null),
  ('db862c78-0912-54e1-b5b5-75238c818d32', 'Wenn Embedding-Vektoren auf eine einheitliche Länge (Norm) von genau 1 normiert sind — welchen Vorteil bringt das für die Ähnlichkeitsberechnung?', 'multiple_choice', '["Die Kosinus-Ähnlichkeit reduziert sich dann auf ein einfaches Skalarprodukt, effizienter berechenbar (GPU-freundlich)", "Weil längere Vektoren mehr Speicherplatz benötigen würden", "Eine willkürliche Konvention ohne technischen Grund", "Aus reinen Datenschutzgründen"]'::jsonb, 56, 'T1', 'T4'),
  ('ba4c76e8-5558-5143-87fa-cb81d8c884bd', 'Was gehört NICHT zu den nativen Bausteinen von Supabase (Backend-Alternative zu n8n)?', 'multiple_choice', '["Edge Functions als Pendant zu n8n-Workflows", "Authentifizierung / User-Management", "Storage für Bilder, Videos und einen Vector Store", "Ein visueller Drag-and-Drop-Editor wie in n8n"]'::jsonb, 58, 'T3', null),
  ('72beeaaa-b2fe-5e45-8262-4dc99494ece7', 'Was macht `JSON.parse`, wenn man einen LLM-Textoutput damit verarbeitet?', 'multiple_choice', '["Sie übersetzt den Text in eine andere Sprache", "Sie wandelt einen Text-String, der wie ein JSON-Objekt aussieht, in ein echtes JSON/JavaScript-Objekt um", "Sie verschlüsselt sensible Felder im JSON-Objekt", "Sie komprimiert das JSON-Objekt, um Tokens zu sparen"]'::jsonb, 61, 'T3', null),
  ('62b184df-06a4-5e00-acc2-11dc0435e375', 'Was wird mit einem "Needle in a Haystack"-Test geprüft, bei dem z. B. das Wort "Banane" mitten in einem langen Dokument versteckt und von einem LLM zuverlässig gefunden wird?', 'multiple_choice', '["Wie schnell ein Modell pro Sekunde Tokens generiert", "Wie viele Parameter ein Modell hat", "Ob ein Modell über ein langes Kontextfenster hinweg auch Information in der Mitte des Dokuments zuverlässig wiederfindet (Stichwort \"Lost in the Middle\"-Phänomen)", "Ob ein Modell zwischen zwei Sprachen unterscheiden kann"]'::jsonb, 63, 'T4', null),
  ('aea1e57b-c88a-56eb-9489-55d9f0fc2137', 'Welche wurde im Kurs NICHT als eine der "3 großen" Adversarial-Attack-Kategorien für Agenten-Systeme genannt?', 'multiple_choice', '["SQL Injection", "Finanzieller Schaden durch Token-Verbrennen", "Deepfake-Video-Generierung", "Knowledge Base Corruption"]'::jsonb, 64, 'T5', 'T2'),
  ('5e90a87a-bad8-54cd-a538-2d201655e8da', 'Es wird zwischen "direkten" und "subtilen" Prompt-Injection- bzw. Jailbreak-Versuchen unterschieden. Welches Beispiel für eine subtile Variante wurde im Kurs genannt?', 'multiple_choice', '["Man stellt dieselbe Frage einfach mehrfach hintereinander", "Man schreibt direkt \"ignoriere alle vorherigen Anweisungen\"", "Man schreibt den Systemprompt in einer anderen Sprache", "Man tarnt die eigentliche Anfrage als Kinderschutz-Anliegen, um an dieselbe verbotene Information zu kommen"]'::jsonb, 66, 'T5', null),
  ('3755c8da-b2ab-5c90-806a-e22b0ade99c2', 'Warum ist das Fine-Tuning eines kompletten LLM aufwendiger und riskanter (Stichwort Catastrophic Forgetting) als das Nachtrainieren eines kleinen Bildklassifizierungs-"Kopfes" auf einem vortrainierten Bildmodell?', 'multiple_choice', '["Text-Fine-Tuning ist technisch unmöglich, LLMs haben keine trainierbaren Gewichte", "Fine-Tuning funktioniert bei beiden gleich gut, nur die Kosten unterscheiden sich", "Bei Bildklassifikation reicht oft das Nachtrainieren eines kleinen \"Kopfes\" auf gefrorenen Features; bei LLMs verändert Fine-Tuning tendenziell mehr Gewichte und kann bereits gelerntes Wissen überschreiben", "Bildmodelle sind grundsätzlich kleiner und günstiger zu trainieren"]'::jsonb, 68, 'T4', 'T1'),
  ('285f43a9-3777-594e-b68c-41c73845e3c4', 'Welche drei klassischen Hauptarten des Machine Learning wurden als Grundlage vorgestellt, um einzuordnen, wie ML-Modelle grundsätzlich lernen?', 'multiple_choice', '["Batch Learning, Online Learning, Federated Learning", "Supervised, Unsupervised, Reinforcement Learning", "Deep Learning, Shallow Learning, Transfer Learning", "Klassifikation, Regression, Clustering"]'::jsonb, 70, 'T4', null),
  ('89bda9da-23d7-52c1-b01f-f87684bc3bca', 'Bei einem Feuerwehr-RAG-Use-Case (Orientierung in Feuerwehrdienstvorschriften bei Großschadenslagen): Was soll das System laut Kurs-Vorgabe explizit NICHT tun?', 'multiple_choice', '["Multiquery nutzen, um Einsatzjargon in \"Beamtendeutsch\" zu übersetzen", "Die relevanten Original-Paragraphen zurückliefern", "Ein Reranking der gefundenen Dokumente durchführen", "Selbstständig eine Entscheidung treffen bzw. eine Lösung vorschlagen"]'::jsonb, 72, 'T1', 'T5'),
  ('4c9429c4-e261-5489-a2c8-8dca623ba8d4', 'Warum wird für das zuverlässige Erkennen personenbezogener Daten (PII) in Freitext eher ein spezialisiertes Named Entity Recognition (NER) Modell statt ein allgemeines LLM empfohlen?', 'multiple_choice', '["LLMs können grundsätzlich keine einzelnen Tokens klassifizieren", "NER-Modelle sind gesetzlich für DSGVO-Konformität vorgeschrieben", "NER-Modelle sind kostenlos, LLMs kosten immer Geld", "NER-Modelle sind genau für diese eine Aufgabe trainiert, brauchen deutlich weniger Parameter/Rechenleistung und sind schneller/günstiger"]'::jsonb, 73, 'T5', 'T4'),
  ('426ce262-910a-5b19-a244-56571fe6323f', 'Was bedeutet ein HTTP-Statuscode im Bereich 400 (4xx) bei einem API-Call, allgemein?', 'multiple_choice', '["Die Verbindung wurde durch eine Firewall blockiert", "Ein Server-Fehler, für den der Client nichts kann", "Ein Fehler auf Client-Seite (z. B. eine ungültige oder fehlerhafte Anfrage)", "Die Anfrage wurde erfolgreich angenommen, das Ergebnis kommt später"]'::jsonb, 76, 'T3', null),
  ('af2ccb84-34f7-5b11-97d9-c71961b98597', 'Warum ist die Überwachung eines Agent-zu-Agent-Systems schwieriger als die eines klassischen Software-Systems mit striktem Datenformat?', 'multiple_choice', '["Weil Text-Kommunikation zwischen Agenten technisch verboten ist", "Weil ein falsch benannter Key in freier Text-Kommunikation keinen harten Fehler wirft und der Fehler sich unbemerkt einschleicht", "Weil Agenten grundsätzlich keine Logs schreiben können", "Weil LLMs grundsätzlich langsamer rechnen als klassische Software"]'::jsonb, 77, 'T2', null),
  ('07801d5f-129e-5940-b09b-d751ee1bef55', 'Wie wird im Kurs das Verhältnis zwischen einem "Router" und einem "Koordinator" als Agent-Design-Pattern beschrieben?', 'multiple_choice', '["Ein Router braucht immer einen Menschen im Loop, ein Koordinator nie", "Ein Koordinator kann nur einen einzigen Agenten aufrufen, ein Router beliebig viele", "Router und Koordinator sind austauschbare Begriffe für dasselbe Pattern", "Jeder Koordinator ist ein Router mit zusätzlicher Funktionalität (einer Feedback-Schleife), aber nicht jeder Router ist ein Koordinator"]'::jsonb, 78, 'T2', null),
  ('5c5d837e-f379-5ab1-b4e2-78942411d5ac', 'Wofür steht die Abkürzung MCP?', 'multiple_choice', '["Model Context Protocol", "Managed Cloud Platform", "Model Calling Pipeline", "Multi-Agent Control Process"]'::jsonb, 80, 'T2', null),
  ('b295b623-0c92-595b-8521-a6bb43a42c8e', 'Warum muss ein Agent beim Aufruf eines MCP-Tools strukturierten Input (passend zum JSON-Schema des Tools) liefern?', 'multiple_choice', '["Weil MCP-Server nur verschlüsselte Anfragen akzeptieren", "Weil der MCP-Server die Anfrage nur korrekt verarbeiten kann, wenn sie dem vom Tool definierten Schema (Parameter-Namen und -Typen) entspricht", "Weil LLMs generell nur XML statt JSON verarbeiten können", "Weil sonst die Tool-Beschreibung nicht mehr geladen werden kann"]'::jsonb, 81, 'T2', null),
  ('e415227c-a7cf-5e9d-9633-3c40a34e5cab', 'Was ist der allgemeine Unterschied zwischen MCP und Agent-to-Agent-Kommunikation (A2A)?', 'multiple_choice', '["Beide regeln ausschließlich die Kommunikation zwischen Agent und Tool, nur von unterschiedlichen Herstellern", "Beide regeln ausschließlich die Kommunikation zwischen Agent und Agent, nur unter unterschiedlichen Namen", "MCP regelt die Kommunikation zwischen Agent und Tool, A2A die Kommunikation zwischen Agent und Agent", "MCP regelt die Kommunikation zwischen Agent und Agent, A2A die Kommunikation zwischen Agent und Tool"]'::jsonb, 82, 'T2', null),
  ('bb5c05ea-f17b-55a1-a2bc-2f78e893ae08', 'Von welchem Unternehmen wurde das "Agent to Agent" (A2A) Protokoll entwickelt?', 'multiple_choice', '["Anthropic", "OpenAI", "Microsoft", "Google"]'::jsonb, 83, 'T2', null),
  ('a5f28a26-1ce6-512a-943f-d4aa40909c65', 'Was ist eine "Agent Card" im A2A-Protokoll?', 'multiple_choice', '["Eine Kreditkarte, über die die API-Kosten eines Agenten abgerechnet werden", "Ein Datenbankeintrag mit der IP-Adresse eines Agenten", "Ein digitaler Ausweis, mit dem sich ein Agent gegenüber einer Firewall authentifiziert", "Eine maschinenlesbare Beschreibung, die zeigt, was ein Agent kann und wie andere mit ihm interagieren sollen — das Pendant zur Tool-Beschreibung bei MCP"]'::jsonb, 85, 'T2', null),
  ('596825ff-fdb1-5167-a569-edf451350baf', 'Welches der folgenden Signale wurde im Kurs NICHT als Hinweis genannt, dass ein Single Agent in ein Multi-Agent-System aufgeteilt werden sollte?', 'multiple_choice', '["Der Agent hat 3 Tools registriert", "Eine Grenzfall-Anfrage liefert ein plausibles, aber falsches Ergebnis", "Die Antwortqualität schwankt stark je nach Art der Anfrage", "Der System-Prompt versucht, mehrere Experten gleichzeitig zu sein"]'::jsonb, 86, 'T2', null),
  ('276d437b-2efa-50fe-883f-a46efbda6499', 'Zu welchem Ergebnis kam ein im Kurs live vorgeführtes Multi-Agent-System bei der Frage "RAG oder Feintuning für ein Wissenssystem"?', 'multiple_choice', '["Beide Ansätze seien gleichwertig, reine Geschmackssache", "Das System konnte sich nicht entscheiden und gab keine Empfehlung", "RAG ist für die meisten Probleme die bessere Wahl, Feintuning eignet sich eher für Stil und Tonalität als für Faktenwissen", "Feintuning ist fast immer überlegen, weil es Tokenkosten spart"]'::jsonb, 87, 'T1', 'T4'),
  ('0c989b87-5bdc-5645-a1f2-2d4a4b70be75', 'Eine sequentielle Agentenkette besteht aus 3 Schritten, jeder mit einer Erfolgswahrscheinlichkeit von 80 %. Wie hoch ist die Gesamterfolgswahrscheinlichkeit ungefähr?', 'estimation', null, 88, 'T2', 'T5'),
  ('bf135a85-82f6-5c86-99d3-b94e70e68604', 'Welches Modell wurde im Kurs empfohlen, um eingehende Prompts schnell auf Prompt-Injection zu klassifizieren?', 'multiple_choice', '["Ein klassisches regelbasiertes Regex-System ganz ohne Machine Learning", "Ein kleines, schnelles Transformer-basiertes Sprachmodell — kein \"Large\" Language Model", "Ein eigens fein-getuntes GPT-4 für Security-Anwendungen", "Das größtmögliche Modell wie Claude Opus, da nur so Injections zuverlässig erkannt werden"]'::jsonb, 90, 'T5', 'T4'),
  ('bb00553c-0988-5c51-b072-02831a3b7187', 'Ein Konzept aus der Unternehmensberatung dient als Kriterium für gute Router-Kategorien: MECE. Wofür steht es?', 'multiple_choice', '["Mutually Exclusive, Collectively Exhaustive", "Multi Endpoint Communication Exchange", "Maximally Exact, Clearly Encoded", "Modular Efficient Category Engine"]'::jsonb, 91, 'T2', null),
  ('b9d7dba2-3b8c-5b02-b55b-9f251318b6df', 'Welche vereinfachte Definition wird im Kurs für einen "Agenten" verwendet, um der Mystifizierung als "KI-Mitarbeiter" entgegenzuwirken?', 'multiple_choice', '["Ein Agent ist ein neuronales Netz mit eigenem Bewusstsein", "Ein Agent ist ein LLM mit einer Knowledge Base und Tools", "Ein Agent ist ein Microservice mit REST-API", "Ein Agent ist ein trainiertes Reinforcement-Learning-Modell"]'::jsonb, 94, 'T2', null),
  ('1c59ed39-98eb-54ed-9f7e-25191e40608e', 'Welches Prinzip wird als Leitlinie dafür genannt, wie sich die Verantwortlichkeiten von Agenten in einem Multi-Agent-System zueinander verhalten sollten?', 'multiple_choice', '["MECE — Mutually Exclusive, Collectively Exhaustive", "KISS — Keep It Simple, Stupid", "DRY — Don''t Repeat Yourself", "YAGNI — You Aren''t Gonna Need It"]'::jsonb, 95, 'T2', null),
  ('cc2054a3-f001-5116-b570-33b1b4ce8b03', 'Welche drei Ebenen der Informationsspeicherung wurden im Kurs für ein agentisches System unterschieden?', 'multiple_choice', '["RAM, SSD, Cloud-Storage", "Agent Context Window (Buffer Memory), Flow State, persistierender Speicher", "Cache, Datenbank, Backup", "Short-Term-, Long-Term-, Working-Memory (aus der Psychologie)"]'::jsonb, 97, 'T2', null),
  ('5f9d1657-6749-5b5c-b40c-a87310de8927', 'Mit welchem Bild wurde im Kurs der Flow State (globale State-Variable im agentischen Graphen) erklärt?', 'multiple_choice', '["Ein Banktresor mit mehreren Schlüsseln", "Eine Blackbox, die niemand einsehen kann", "Ein privates Tagebuch, das nur ein Agent lesen darf", "Ein öffentlicher Park bzw. Brunnen, den alle nutzen dürfen, der aber durch einen einzelnen Agenten \"vergiftet\" werden kann"]'::jsonb, 98, 'T2', null),
  ('4b58bd14-0a0e-5306-9c4d-5459a0472dc9', 'Supabase Edge Functions haben ein technisches Zeitlimit für die maximale Laufzeit. Wie viele Sekunden darf eine Edge Function auf dem **Free Plan** maximal laufen?', 'estimation', null, 99, 'T3', 'T2'),
  ('4ec4fe28-914f-5ee7-b5e0-fda18998c5f9', 'Welche vier agentenspezifischen Fehlertypen (Error Modes) wurden im Kurs bei Multi-Agenten-Workflows besprochen?', 'multiple_choice', '["Rate Limit, Auth Error, 404, 500", "Syntax Error, Runtime Error, Logic Error, Compile Error", "Timeout, Nachrichtenverlust, teilweise Ausführung, Agent-Nichtverfügbarkeit", "Overfitting, Underfitting, Bias, Varianz"]'::jsonb, 100, 'T2', 'T5'),
  ('8986731b-83bb-5dbc-a697-afdcb85a34fd', 'Welche Retry-Strategie wurde im Kurs als empfohlene Vorgehensweise für externe APIs vorgestellt, bei der sich die Wartezeit zwischen Versuchen jedes Mal verdoppelt?', 'multiple_choice', '["Begrenzter Retry ohne Zeitdelta", "Exponentielles Backoff (in der Praxis oft zusätzlich mit Jitter kombiniert)", "Circuit Breaker", "Sofortiger Retry"]'::jsonb, 102, 'T3', 'T2'),
  ('3a16d98a-0f16-58cf-9f88-8c15fef56845', 'Was ist arXiv?', 'multiple_choice', '["Ein bezahlter Peer-Review-Journal-Verlag", "Ein Code-Repository ausschließlich für ML-Wettbewerbe", "Eine kostenlose Preprint-Bibliothek, auf der Forscher Paper vor der Peer-Review-Veröffentlichung hochladen können", "Ein interner MSIT-Datenspeicher für Vorlesungsmaterial"]'::jsonb, 103, 'T4', null),
  ('76bd378e-c9dc-504a-882a-393b8d3e4a19', 'Wie viele Zustände hat ein Circuit Breaker im vorgestellten Modell?', 'multiple_choice', '["3 (geschlossen, offen, halboffen)", "5", "2 (Ein/Aus)", "4 (inkl. Cooldown)"]'::jsonb, 104, 'T3', 'T2'),
